*(5) To get the current industry code; 
data CompNames; set lc.CompNames; run;
proc sort data=CompNames nodupkey; by gvkey; run;

proc sql; 
     create table Comp_Vars_temp4 as 
     select a.*, e.sic
     from Comp_Vars_temp3 a left join CompNames e
     on a.gvkey=e.gvkey;
     quit;

* (6) To get the Geo location variables; 
proc sql; 
     create table lc.compvars as 
     select a.*, b.addzip, b.ipodate, b.state, b.county, b.city
     from Comp_Vars_temp4 a left join lc.company b 
     on a.gvkey=b.gvkey; 
     quit; 

