Data lc.ResPeriod_M1; 
     Set ResPeriod;
     ResReason = RES_ACC_RES_FKEY_LIST;
     Array R[30] $50 R1 - R30; 
     I = 0;
     L = 0;             
     Do Until (ResReason = "");
           I = I + 1;
           If Index(ResReason, "|") >= 0 Then L = Index(ResReason, "|") - 1;
                                         Else L = Length(ResReason);                                                                      
           R[I] = Substr (ResReason, 1, L);
           ResReason = Substr (ResReason, L + 2);
     End;
     Output; 
     Drop ResReason L;
     Run;

